mapper.select:
select  from todo_acceptance_ref_mapping m
left join todo_acceptance_scenario s on s.scenario_id=m.scenario_id
left join sys_user owner on owner.user_id=m.owner_user_id
left join sys_user reviewer on reviewer.user_id=m.reviewer_user_id

  m.template_code=#{templateCode}
  and m.dimension_code=#{dimensionCode}
  and m.status=#{status}

order by m.template_code,m.dimension_code,m.acceptance_ref
